.todo-app {
  max-width: 600px;
  margin: 0 auto;
  padding: 24px 20px;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.header h1 {
  font-size: 32px;
  margin: 0;
}

.theme-toggle {
  background: none;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 16px;
  cursor: pointer;
  transition: background 0.2s;
}

.theme-toggle:hover {
  background: var(--code-bg);
}

.input-section {
  display: flex;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 16px;
  background: var(--bg);
  color: var(--text-h);
  outline: none;
  transition: border-color 0.2s;
}

.todo-input:focus {
  border-color: var(--accent);
}

.add-button {
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 16px;
  cursor: pointer;
  transition: background 0.2s;
}

.add-button:hover {
  background: #9a2bff;
}

.filter-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.filters {
  display: flex;
  gap: 8px;
}

.filters button {
  flex: 1;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s;
}

.filters button.active {
  background: var(--accent-bg);
  border-color: var(--accent);
  color: var(--accent);
}

.open-count {
  font-size: 14px;
  color: var(--text);
  margin: 0;
}

.todo-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}

.todo-label {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
}

.todo-checkbox {
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.todo-text {
  font-size: 16px;
  color: var(--text-h);
  transition: color 0.2s, text-decoration 0.2s;
}

.todo-text.completed {
  color: var(--text);
  text-decoration: line-through;
}

.todo-actions {
  display: flex;
  gap: 8px;
}

.edit-button,
.delete-button {
  background: none;
  border: none;
  font-size: 14px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: background 0.2s;
}

.edit-button:hover {
  background: var(--code-bg);
}

.delete-button:hover {
  background: rgba(239, 68, 68, 0.1);
  color: #ef4444;
}

.empty-state {
  text-align: center;
  color: var(--text);
  font-size: 16px;
  padding: 24px;
}

