  // Find the theme toggle button using a selector
  const toggle = await tools.playwright.browser_find({ text: 'Dark Mode' });
  return { toggle };
} catch (e) {
  return { error: String(e) };
}

try {
  // Use browser_click with a selector
  const click = await tools.playwright.browser_click({
    target: 'button.theme-toggle'
  });
  return { click: String(click).slice(0, 200) };
} catch (e) {
  return { error: String(e) };
}

